import { bigint, timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key generated by the database. */
export const id = () => uuid("id").primaryKey().defaultRandom();

/** All timestamps are timestamptz, stored in UTC. */
export const createdAt = () => timestamp("created_at", { withTimezone: true, mode: "date" }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true, mode: "date" })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

/**
 * Money in integer minor units (cents, sen). bigint because KHR amounts in minor units overflow int4.
 * `mode: "number"` is exact up to 2^53, far beyond any amount here, and keeps arithmetic out of floats.
 */
export const minor = (name: string) => bigint(name, { mode: "number" });
